--
-- Table structure for table `relevant`
--

DROP TABLE IF EXISTS `relevant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `relevant` (
  `kod` varchar(4) NOT NULL,
  `long_name` varchar(255) DEFAULT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `sample` varchar(1000) DEFAULT NULL,
  `sig_subject` int(11) DEFAULT NULL,
  `sig_subject2` int(11) DEFAULT NULL COMMENT 'альтернативный якорь субъекта',
  `sig_subject3` int(11) DEFAULT NULL,
  `sig_subject4` int(11) DEFAULT NULL,
  `sig_object` int(11) DEFAULT NULL,
  `sig_object2` int(11) DEFAULT NULL,
  `sig_object3` int(11) DEFAULT NULL,
  `sig_object4` int(11) DEFAULT NULL,
  `is_symmetric` tinyint(4) NOT NULL DEFAULT '0',
  `is_transitive` tinyint(4) NOT NULL DEFAULT '0',
  `inverse_kod` varchar(4) DEFAULT NULL,
  PRIMARY KEY (`kod`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `relevant`
--

LOCK TABLES `relevant` WRITE;
/*!40000 ALTER TABLE `relevant` DISABLE KEYS */;
INSERT INTO `relevant` VALUES ('0','no data','Служебный код: связь не установлена или не проверялась.','Любая непроверенная пара.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('1','incomparable','У понятий нет общего рода и основания для сравнения объёмов.','стол — честность.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('10','full inclusion (subordination) [deprecated]','УСТАРЕВШИЙ: слито с кодом 14. Включение объёма понятия в онтологии всегда является родовидовым отношением.','Использовать kod 14.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('11','universe (discourse context)','Базовый контекст, в рамках которого сравниваются объёмы понятий и истинны связи: бытовой, научный, или конкретная область (биология, медицина). Одна и та же пара понятий может иметь разные связи в разных универсумах. Исчерпывающие отношения (64) определены только внутри заданного универсума.','в бытовом универсуме: томат — овощ; в универсуме биологии: томат — фрукт (ягода).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('12','domain-related','Принадлежность понятия к научной или иной области знаний (домену).','спина — анатомия; интеграл — математика.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('13','family (genus-to-genus) [deprecated]','УСТАРЕВШИЙ: слито с кодом 14. Родовое отношение едино на всех уровнях таксономии.','Использовать kod 14.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('14','genus (is-a)','Вид включён в род: dh1 — вид (или единичное понятие), dh2 — род. Наследование признаков сверху вниз, транзитивно. Пары только внутри одного корня.','стол — мебель; Лондон — столица (единичное понятие как вид).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,NULL),('15','essential attribute','Признак, без которого предмет не относится к данному виду; входит в определение понятия. dh2 — признак (корень \'свойство\'), dh1 — предмет.','разумность — человек; наличие страниц — книга.',16,2535,1913,NULL,18,1913,NULL,NULL,0,0,NULL),('20','attribute','Атрибуция: предмет и его качество, компонент, функция или способность. Вид выводится по корню объекта, степень — в strength.','чашка белая; чашка с ручкой; нож — резать.',16,2535,1913,20,18,17,2535,1913,0,0,NULL),('21','function (purpose)','dh1 (предмет, обычно артефакт) предназначен для dh2 (действие). Степень — в strength.','нож — резать; мост — соединять.',17,NULL,1913,NULL,2535,1913,NULL,NULL,0,0,NULL),('22','agent (capable of)','dh1 (предмет, обычно организм) способен производить dh2 (действие).','птица — летать; человек — мыслить.',17,NULL,NULL,NULL,2535,NULL,NULL,NULL,0,0,NULL),('23','material','dh1 (предмет) изготовлен из dh2 (вещество). Степень — в strength (монета — металл 95, стол — дерево 70).','стол — дерево; монета — металл.',17,NULL,NULL,NULL,21,NULL,NULL,NULL,0,0,NULL),('24','content (intended content)','dh1 (ёмкость, сосуд, упаковка) предназначен для хранения/подачи dh2 (вещество или предмет).','кофейная чашка — кофе; солонка — соль; ваза — цветы.',17,NULL,NULL,NULL,21,17,NULL,NULL,0,0,NULL),('25','application (acts upon)','dh1 (инструмент) предназначен для воздействия на dh2 (предмет).','открывалка — бутылка; удочка — рыба; пилочка — ногти.',17,NULL,NULL,NULL,17,NULL,NULL,NULL,0,0,NULL),('26','user (intended user)','dh1 (предмет) предназначен для пользователя dh2 (предмет-агент).','детский стул — ребёнок; будка — собака.',17,NULL,NULL,NULL,17,NULL,NULL,NULL,0,0,NULL),('27','patient (object of action)','dh1 (действие или процесс) направлено на dh2 как на объект: предмет, свойство или явление. Не носитель процесса и не исполнитель. Степень — в strength.','читать — книга; строить — сооружение; психологическое исследование — поведение; исследование сна — сон.',2535,1913,NULL,NULL,17,18,1913,2535,0,0,NULL),('30','coextensive (equal scope)','Объёмы совпадают полностью, содержания различны. Каждый элемент одного есть элемент другого.','утренняя звезда — вечерняя звезда (Венера).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('40','overlap','Объёмы понятий частично пересекаются. Степень пересечения — в strength (0-100): 70 = сильное, 50 = примерно половина, 5 = незначительное, NULL = пересечение возможно, но не зафиксировано.','студент — спортсмен (70); певец — шахтёр (5).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL),('49','complementary [deprecated]','УСТАРЕВШИЙ: слито с кодом 62. Системные пары (ключ — замок) взаимно предполагают друг друга.','Использовать kod 62.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('60','incompatible','Объёмы не пересекаются, степень/тип не установлены (заголовок серии 61-64).','Промежуточный код.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('61','coordinate (co-hyponyms)','Виды одного рода, объёмы не пересекаются; не являются ни контрарными, ни контрадикторными.','тополь — берёза (виды деревьев).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,'61'),('62','mutually implying (converses)','Взаимная импликация существования; включает конверсивные (обратные) роли одного отношения и системные пары.','муж — жена; купить — продать; северный полюс — южный полюс.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,'62'),('63','contrary (opposite)','Крайние виды одного рода, между ними есть середина; не могут быть истинны одновременно, но могут быть оба ложны.','белый — чёрный; храбрость — трусость.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,'63'),('64','contradictory','Исчерпывающая дихотомия A / не-A: не могут быть одновременно ни истинны, ни ложны.','живой — мёртвый; чётный — нечётный.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,'64'),('70','causal (produces)','dh1 — причина, dh2 — следствие. Связь между корнями \'действие\'/\'предмет\'. Транзитивно по цепочкам причин.','огонь — дым; вирус — болезнь.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('71','hindrance (prevents)','dh1 препятствует или устраняет dh2 (отрицательная каузальность).','прививка — болезнь; тормоз — движение.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('72','temporal precedence','dh1 типично предшествует dh2 в одном процессе. Направленное, нетранзитивно в обратную сторону.','посев — уборка; гроза — ливень.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL),('73','simultaneity','dh1 и dh2 типично происходят одновременно как стороны одного события. Симметрично.','гром — молния.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,'73'),('74','dependence','dh1 функционально зависит от dh2: не существует или не работает без него. Направленное.','application software — operating system',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL);
/*!40000 ALTER TABLE `relevant` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `universum`
